    """The final path component, if any."""
    tail = self._tail
    if not tail:
        return ''
    return tail[-1]

@property
def suffix(self):
    """
    The final component's last suffix, if any.

    This includes the leading period. For example: '.txt'
    """
    name = self.name
    i = name.rfind('.')
    if 0 < i < len(name) - 1:
        return name[i:]
    else:
        return ''

@property
